#include <iostream>
#include <string>
#include <iomanip>

class CommissionEmployee {
public:
    CommissionEmployee(std::string first, std::string last, std::string ssn, double sales, double rate)
        : firstName(std::move(first)), lastName(std::move(last)), socialSecurityNumber(std::move(ssn)),
          grossSales(sales >= 0.0 ? sales : 0.0),
          commissionRate((rate > 0.0 && rate < 1.0) ? rate : 0.0) {}

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }
    double getGrossSales() const { return grossSales; }
    double getCommissionRate() const { return commissionRate; }

    double earnings() const { return commissionRate * grossSales; }

    void print() const {
        std::cout << "commission employee: " << firstName << ' ' << lastName
                  << "\nsocial security number: " << socialSecurityNumber
                  << "\ngross sales: " << grossSales
                  << "\ncommission rate: " << commissionRate;
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales;
    double commissionRate;
};

class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(std::string first, std::string last, std::string ssn,
                               double sales, double rate, double salary)
        : CommissionEmployee(std::move(first), std::move(last), std::move(ssn), sales, rate),
          baseSalary(salary >= 0.0 ? salary : 0.0) {}

    void setBaseSalary(double salary) {
        baseSalary = (salary >= 0.0) ? salary : 0.0;
    }
    double getBaseSalary() const { return baseSalary; }

    // Access base data safely via public accessors instead of direct private access
    double earnings() const {
        return getBaseSalary() + (getCommissionRate() * getGrossSales());
    }

    void print() const {
        std::cout << "base-salaried ";
        CommissionEmployee::print();
        std::cout << "\nbase salary: " << baseSalary << '\n';
    }

private:
    double baseSalary;
};

int main() {
    std::cout << std::fixed << std::setprecision(2);
    BasePlusCommissionEmployee emp("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);
    emp.print();
    std::cout << "total earnings: $" << emp.earnings() << '\n';
    return 0;
}

#include <iostream>
#include <string>

class Person {
public:
    Person(std::string name, std::string id)
        : fullName(std::move(name)), idNumber(std::move(id)) {}

    virtual ~Person() = default;

protected:
    // Protected members are accessible by derived classes directly
    std::string fullName;
    std::string idNumber;
};

class Student : public Person {
public:
    Student(std::string name, std::string id, double gpa)
        : Person(std::move(name), std::move(id)), gpaScore(gpa) {}

    void display() const {
        // Direct access to protected members fullName and idNumber
        std::cout << "Student: " << fullName 
                  << " | ID: " << idNumber 
                  << " | GPA: " << gpaScore << '\n';
    }

private:
    double gpaScore;
};

int main() {
    Student s("Alice Smith", "ST-1042", 3.85);
    s.display();
    return 0;
}
